function expenseParseEntry(s){
  s=String(s||'').trim(); if(!s) return { error:'空' };
  var parts = s.indexOf(',')>=0 ? s.split(',') : s.split(/\s+/);
  var amount=Number(parts[0]);
  if(!isFinite(amount)) return { error:'金额非法' };
  return { amount:amount, cat:(parts[1]||'').trim(), date:(parts[2]||'').trim(), note:(parts[3]||'').trim() };
}
function expenseSummary(list){
  var total=0, byCat={}, byMonth={};
  for(var i=0;i<list.length;i++){ var e=list[i]; total+=e.amount;
    var c=e.cat||'未分类'; byCat[c]=(byCat[c]||0)+e.amount;
    var mk=String(e.date||'').slice(0,7); if(mk) byMonth[mk]=(byMonth[mk]||0)+e.amount;
  }
  function rnd(x){ return Math.round(x*100)/100; }
  var bc={}, bm={};
  for(var k in byCat) bc[k]=rnd(byCat[k]);
  for(var k2 in byMonth) bm[k2]=rnd(byMonth[k2]);
  return { total:rnd(total), byCat:bc, byMonth:bm };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { expenseParseEntry:expenseParseEntry, expenseSummary:expenseSummary };
}
if (typeof window !== 'undefined') {
  window.ExpenseForgePure = { expenseParseEntry:expenseParseEntry, expenseSummary:expenseSummary };
}
